powerpagecomponent.content:
{
  "displayorder": 7,
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "parentpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "partialurl": "Inbox",
  "isroot": false,
  "rootwebpageid": "03598567-f022-4a29-9e1d-5f3c3ee18b0c",
  "title": "Inbox",
  "summary": "<p>This is a sample landing page designed to be a starting point for your website</p>",
  "copy": "{% include 'cmdspp_Loader' %}
<div class="cmdspp-inbox-container">

    <!-- LEFT PANEL -->

    <div class="cmdspp-thread-panel">

        <div class="cmdspp-search-container">
            <img src="/cmdspp_SearchIcon"/>
            <input type="text"
                   id="cmdspp-search"
                   placeholder="Search messages..." />
        </div>

        <div id="cmdspp-thread-list"></div>

    </div>

    <!-- RIGHT PANEL -->

    <div class="cmdspp-message-panel">

        <div class="cmdspp-toolbar">

            <button id="cmdspp-btn-reply"
                    class="cmdspp-toolbar-btn">
                ↩ Reply
            </button>

            <button id="cmdspp-btn-markread"
                    class="cmdspp-toolbar-btn">
                <img src="/cmdspp_MarkRead"/> Mark Read
            </button>

            <button id="cmdspp-btn-delete"
                    class="cmdspp-toolbar-btn cmdspp-danger">
                <img src="/cmdspp_DeleteIcon"/> Delete
            </button>

        </div>

        <div id="cmdspp-message-view">

            <div class="cmdspp-empty-state">

                <div class="cmdspp-empty-icon">
                    <img src="/cmdspp_SendMessage"/>
                </div>

                <h3 id="cmdspp-inbox-placeholder-heading" class="cmdspp-inbox-placeholder-heading">Select a message</h3>

                <p id="cmdspp-inbox-placeholder-subheading" class="cmdspp-inbox-placeholder-subheading">
                    Choose a message from the list to read it
                </p>

            </div>

        </div>

    </div>

</div>",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "hiddenfromsitemap": true,
  "sharedpageconfiguration": false,
  "feedbackpolicy": 756150000,
  "customcss": ".cmdspp-inbox-container{
    display:flex;
    height:calc(100vh - 65px);
    background:#f8fafc;
}

.cmdspp-thread-panel{
    width:320px;
    height: 100vh;
    border-right:1px solid #e5e7eb;
    background:#fff;
    overflow-y:auto;
}

.cmdspp-search-container{
    padding:12px;
    border-bottom: 1px solid #F9FAFB;
    img{
        position: absolute;
        left: 24px;
        top: 23px;
    }
}

.cmdspp-search-container input{
    width:100%;
    border:1px solid #F3F4F6;
    border-radius:10px;
    background: #F9FAFB;
    padding:12px;
    height: 34px;
    font-weight: 400 !important;
    font-size: 12px;
    line-height: 100%;
    letter-spacing: 0px;
    padding-left: 35px !important;
    outline: none;
}

#cmdspp-search::placeholder{
    color: #5A709999;
    opacity:1;
}

.cmdspp-search-container input:focus{
    box-shadow: 0px 0px 0px 1px #6C8EEF inset, 0px 0px 0px 2px #D6ECFF;
}

.cmdspp-thread-item{
    display:flex;
    gap:10px;
    padding: 12px 14px;
    cursor:pointer;
    border-bottom:1px solid #F9FAFB;
    height: 102px;
    overflow:hidden;
}

.cmdspp-thread-item:hover,
.cmdspp-thread-item-unread
{
    background: #0B3A6F0F;
}

.cmdspp-thread-item.active{
    background: #0B3A6F0F;
}

.cmdspp-avatar{
    color:#ffffff;
    display:flex;
    justify-content:center;
    align-items:center;
    flex-shrink:0;
    width: 32px;
    height: 32px;
    opacity: 1;
    border-radius: 33554400px;
    background: #274463;
}

.cmdspp-thread-content{
    flex:1;
    min-width:0; /* critical */
    overflow:hidden;
}

.cmdspp-thread-name,
.cmdspp-thread-subject{
font-weight: 400 !important;
font-size: 11px;
line-height: 16.5px;
letter-spacing: 0px;
color: #0B3A6F;
}

.cmdspp-thread-subject{
    margin-top:2px;
}

.cmdspp-thread-preview{
    font-weight: 400 !important;
font-size: 10px;
line-height: 15px;
letter-spacing: 0px;
color: #5A7099;
}

.cmdspp-thread-subject,
.cmdspp-thread-preview{
width:100%;
white-space:nowrap;
overflow:hidden;
text-overflow:ellipsis;
}

.cmdspp-thread-bottom{
    display: flex;
    justify-content: space-between;
    margin-top: 6px;
}

.cmdspp-thread-messageType{
    width: 38px;
height: 19px;
opacity: 1;
padding-top: 2px;
padding-right: 6px;
padding-bottom: 2px;
padding-left: 6px;
border-radius: 33554400px;
background: #0B3A6F12;
font-weight: 400 !important;
font-style: Regular;
font-size: 10px;
line-height: 15px;
letter-spacing: 0px;
color: #0B3A6F;
}

.cmdspp-thread-time{
    font-weight: 400 !important;
font-size: 10px;
line-height: 15px;
letter-spacing: 0px;
color: #5A7099;
    flex-shrink:0;
}

.cmdspp-message-panel{
    flex:1;
    display:flex;
    flex-direction:column;
}

.cmdspp-toolbar{
    display:flex;
    justify-content:flex-end;
    height: 59px;
    padding:15px;
    background:#ffffff;
    border-bottom:1px solid #F3F4F6;
}

.cmdspp-toolbar-btn{
    border:none;
    background:none;
    cursor:pointer;
    font-weight: 400 !important;
font-style: Regular;
font-size: 12px;
line-height: 16px;
letter-spacing: 0px;
text-align: center;
color: #5A7099;
    img{
        margin-right: 1.5px;
        margin-bottom: 2px;
    }
}

.cmdspp-danger{
    color:#FB2C36;
}

#cmdspp-message-view{
    display: contents;
}
.cmdspp-empty-state{
    height:100%;
    display:flex;
    flex-direction:column;
    justify-content:center;
    align-items:center;
    color:#64748b;
    h3{
        margin-top: 16px;
        margin-bottom: 0px;
        font-weight: 600 !important;
        font-style: Semi Bold;
        font-size: 16px;
        line-height: 24px;
        letter-spacing: 0px;
        text-align: center;
        color: #0B3A6F;
    }
    p{
        font-weight: 400 !important;
        font-style: Regular;
        font-size: 14px;
        line-height: 20px;
        letter-spacing: 0px;
        text-align: center;
        color: #5A7099;
    }
}

.cmdspp-empty-icon{
    width: 64px;
    height: 64px;
    opacity: 1;
    border-radius: 16px;
    background: #0B3A6F0F;
    padding: 18px;
}

.cmdspp-message-card{
    margin:21px;
    background:#ffffff;
    border-radius: 16px;
    border: 1px solid #0000000D;
    box-shadow: 0px 1px 2px -1px #0000001A,0px 1px 3px 0px #0000001A;
    padding:20px;
}

.cmdspp-message-subject{
    font-weight: 400 !important;
    font-size: 16px;
line-height: 22px;
letter-spacing: 0px;
color: #0B3A6F;
    margin-bottom:10px;
}

.cmdspp-message-meta{
    display:flex;
    gap:10px;
    align-items:center;
    margin-bottom:16px;
}

.cmdspp-message-info{
display:flex;
align-items:center;
height: 42px;
opacity: 1;
gap: 12px;
padding-top: 12px;
padding-bottom: 12px;
border-top: 1px solid #F3F4F6;
border-bottom: 1px solid #F3F4F6;
margin-bottom:16px;
font-weight: 400 !important;
font-size: 12px;
line-height: 16px;
letter-spacing: 0px;
color: #5A7099;
img{
    margin-right: 6px;
}
}

.cmdspp-message-body{
    font-weight: 400 !important;
font-size: 14px;
line-height: 22.75px;
letter-spacing: 0px;
color: #0B3A6F;
white-space: pre-wrap;
}

.cmdspp-section-title{
    margin-top:20px;
    margin-bottom:10px;
    color:#64748b;
    font-size:12px;
    font-weight:600;
}

.cmdspp-attachment-list{
    display:flex;
    gap:12px;
}

.cmdspp-attachment{
    border:1px solid #e5e7eb;
    border-radius:10px;
    padding:10px;
    min-width:220px;
}

.cmdspp-reply-box{
    margin:20px;
    background:#fff;
    border:1px solid #e5e7eb;
    border-radius:18px;
}

.cmdspp-reply-header{
    display:flex;
    justify-content:space-between;
    padding:15px 20px;
    border-bottom:1px solid #e5e7eb;
}

.cmdspp-reply-text{
    width:100%;
    min-height:180px;
    border:none;
    outline:none;
    resize:none;
    padding:20px;
}

.cmdspp-reply-footer{
    display:flex;
    gap:10px;
    padding:15px;
}

.cmdspp-send-btn{
    border:none;
    background:#21417a;
    color:#fff;
    padding:10px 20px;
    border-radius:25px;
}

.cmdspp-attach-btn{
    border:1px solid #21417a;
    background:#fff;
    color:#21417a;
    padding:10px 20px;
    border-radius:25px;
}

#cmdspp-btn-reply,
.cmdspp-inline-reply-btn,
.cmdspp-section-title,
.cmdspp-attachment-list{
    display: none !important;
}",
  "customjavascript": "/* ==========================================
   GLOBALS
========================================== */

let cmdsppThreadData = [];

window.cmdsppSelectedThreadId = null;


/* ==========================================
   LOAD INBOX
========================================== */

async function cmdsppLoadInbox(isSearch,searchstring) {

    try {

        
        //Uncomment once flow is ready
        showLoader(" ");
        $(".cmdspp-inbox-container").hide();

        const result =
            await cmdsppExecuteInboxAction(
                {
                    userId: window.cmdsppUserId,
                    transType: isSearch? "searchEmails" : "fetchThreads",
                    rowCount:5000,
                    searchString:searchstring
                }
            );

        cmdsppThreadData = []
        let res =  result.data || [];

        res.forEach((data)=>{
            data.senderName = data.senderName ? data.senderName : "System Admin"
            data.modifiedTime = cmdsppFormatInboxDate(data.modifiedTime)
            cmdsppThreadData.push(data)
        })

        if(res.length == 0){
            // $("#cmdspp-inbox-placeholder-heading").text = "No messages found in your Secure Inbox."
            document.getElementById("cmdspp-inbox-placeholder-heading").textContent ="No messages found in your Secure Inbox";
            document.getElementById("cmdspp-inbox-placeholder-subheading").textContent ="";

            // $("#cmdspp-inbox-placeholder-subheading").hide();
        }
        $(".cmdspp-inbox-container").show();
        hideLoader();
        window.originalInboxData = cmdsppThreadData;

        cmdsppRenderThreads(
            cmdsppThreadData
        );

    }
    catch (error) {

        console.error(
            "Inbox load failed",
            error
        );
        hideLoader();

    }

}


/* ==========================================
   RENDER THREADS
========================================== */

function cmdsppRenderThreads(data) {

    let html = "";

    data.forEach(thread => {

        html += `
            <div class="cmdspp-thread-item ${!thread.readInd ? 'cmdspp-thread-item-unread' : ''}"
                 data-threadid="${thread.threadId}">

                <div class="cmdspp-avatar">
                    ${thread.senderName.charAt(0)}
                </div>

                <div class="cmdspp-thread-content">

                    <div class="cmdspp-thread-name">
                        ${thread.senderName}
                    </div>

                    <div class="cmdspp-thread-subject">
                        ${thread.emailSubject}
                    </div>

                    <div class="cmdspp-thread-preview">
                        ${thread.emailBody}
                    </div>

                    <div class="cmdspp-thread-bottom">
                         <div class="cmdspp-thread-messageType">
                           ${thread.messageType}
                        </div>

                        <div class="cmdspp-thread-time">
                           ${thread.modifiedTime}
                        </div>
                    </div>

                </div>

            </div>
        `;
    });

    $("#cmdspp-thread-list")
        .html(html);

}

function cmdsppSearchInbox(searchText) {

    const search =
        searchText.trim().toLowerCase();

    if (!search) {
        return window.originalInboxData;
    }

    return window.originalInboxData.filter(item => {

        const senderEmail =
            (item.senderEmail || "")
                .toLowerCase();

        const emailSubject =
            (item.emailSubject || "")
                .toLowerCase();

        const emailBody =
            (item.emailBody || "")
                .toLowerCase();

        return (
            senderEmail.includes(search) ||
            emailSubject.includes(search) ||
            emailBody.includes(search)
        );

    });

}


/* ==========================================
   OPEN THREAD
========================================== */

async function cmdsppOpenThread(threadId) {

    window.cmdsppSelectedThreadId =
        threadId;


    const result =
        await cmdsppExecuteInboxAction(
            {
                threadId: threadId,
                transType: "fetchThreadDetail"
            }
        );

    const messages = result.data || [];


    const thread =
        cmdsppThreadData.find(
            x => x.threadId == threadId
        );

    let attachmentHtml = "";

    // thread.attachments.forEach(att => {

    //     attachmentHtml += `
    //         <div class="cmdspp-attachment">

    //             <div class="cmdspp-attachment-name">
    //                 ${att.name}
    //             </div>

    //             <div class="cmdspp-attachment-size">
    //                 ${att.size}
    //             </div>

    //         </div>
    //     `;
    // });

    const messagesHtml = messages.map(message => `

    <div class="cmdspp-message-card">

        <div class="cmdspp-message-subject">
            ${message.emailSubject}
        </div>

        <div class="cmdspp-message-meta">

            <div class="cmdspp-avatar">
                ${message.senderFirstName ? message.senderFirstName.charAt(0) : "S"}
            </div>

            <div>

                <div class="cmdspp-thread-name">
                    ${message.senderFirstName ? message.senderFirstName +' ' +senderLastName : 'System Admin'}
                </div>

                <div class="cmdspp-thread-preview">
                    ${message.senderEmail}
                </div>

            </div>

        </div>

        <div class="cmdspp-message-info">

            <span>
                <img src="/cmdspp_EmailNormal"/>${thread.messageType}
            </span>

            <span>•</span>

            <span>
                <img src="/cmdspp_ProviderTypeIcon"/>${message.providerType}
            </span>

            <span>•</span>

            <span>
                ${cmdsppFormatInboxDate(message.createdTime,true)}
            </span>

        </div>

        <div class="cmdspp-message-body">${message.emailBody}</div>

    </div>

`).join('');

    $("#cmdspp-message-view").html(`
        ${messagesHtml}
    `);

    $(".cmdspp-thread-item")
        .removeClass("active");

    $(
        `.cmdspp-thread-item[data-threadid="${threadId}"]`
    ).addClass("active");

}


/* ==========================================
   SHOW REPLY PANEL
========================================== */

function cmdsppShowReplyPanel() {

    const thread =
        cmdsppThreadData.find(
            x =>
            x.threadId ==
            window.cmdsppSelectedThreadId
        );

    if (!thread) {
        return;
    }

    $("#cmdspp-reply-container")
        .html(`

        <div class="cmdspp-reply-box">

            <div class="cmdspp-reply-header">

                <div>
                    ↩ Reply to
                    <strong>
                        ${thread.senderName}
                    </strong>
                    &lt;${thread.senderEmail}&gt;
                </div>

                <button
                    id="cmdspp-close-reply"
                    type="button">

                    ✕

                </button>

            </div>

            <textarea
                id="cmdspp-reply-text"
                class="cmdspp-reply-text"
                placeholder="Write your reply..."></textarea>

            <div class="cmdspp-reply-footer">

                <button
                    id="cmdspp-send-reply"
                    class="cmdspp-send-btn">

                    Send

                </button>

                <button
                    id="cmdspp-attach-document"
                    class="cmdspp-attach-btn">

                    Attach Document

                </button>

            </div>

        </div>

    `);

}


/* ==========================================
   SEND REPLY
========================================== */

async function cmdsppSendReply() {

    const reply =
        $("#cmdspp-reply-text")
            .val()
            .trim();

    if (!reply) {

        alert(
            "Please enter a reply."
        );

        return;
    }

    try {

        await cmdsppExecuteInboxAction(
            "REPLY",
            {
                threadId:
                    window.cmdsppSelectedThreadId,

                message:
                    reply
            }
        );

        $("#cmdspp-reply-container")
            .empty();

        alert(
            "Reply sent successfully."
        );

    }
    catch (error) {

        console.error(
            error
        );

        alert(
            "Unable to send reply."
        );
    }

}


/* ==========================================
   MARK READ
========================================== */

async function cmdsppMarkRead() {

    await cmdsppExecuteInboxAction({
                threadId: window.cmdsppSelectedThreadId,
                transType: "markThreadAsRead"
            });
    window.location.reload();       

}


/* ==========================================
   DELETE THREAD
========================================== */

async function cmdsppDeleteThread() {

    await cmdsppExecuteInboxAction({
                threadId: window.cmdsppSelectedThreadId,
                transType: "deleteThread"
            });

    window.location.reload();        

}


/* ==========================================
   EVENTS
========================================== */

$(document)

    .on(
        "click",
        ".cmdspp-thread-item",
        function () {

            const threadId =
                $(this)
                    .data("threadid");

            cmdsppOpenThread(
                threadId
            );

        }
    )

    .on(
        "click",
        "#cmdspp-inline-reply-btn",
        function () {

            cmdsppShowReplyPanel();

        }
    )

    .on(
        "click",
        "#cmdspp-btn-reply",
        function () {

            cmdsppShowReplyPanel();

        }
    )

    .on(
        "click",
        "#cmdspp-send-reply",
        function () {

            cmdsppSendReply();

        }
    )

    .on(
        "click",
        "#cmdspp-close-reply",
        function () {

            $("#cmdspp-reply-container")
                .empty();

        }
    );


$("#cmdspp-btn-markread").on(
    "click",
    function () {

        cmdsppMarkRead();

    }
);


$("#cmdspp-btn-delete").on(
    "click",
    function () {

        cmdsppDeleteThread();

    }
);


/* ==========================================
   SEARCH
========================================== */

$("#cmdspp-search").on(
    "keyup",
    function () {

        const search =
            $(this)
                .val()
                .toLowerCase();

        // if(search.length >=3){
        //     // cmdsppLoadInbox(true,search)
        // }
        const filteredData =cmdsppSearchInbox(search);
        cmdsppRenderThreads(filteredData);
        

    }
);


/* ==========================================
   INIT
========================================== */

$(document).ready(function () {

    cmdsppLoadInbox();

});"
}
